{
  "name": "线段图形标注对象",
  "name_en": "Line Graphic Annotation",
  "manufacturer": "Nion",
  "description": "这不是独立物理仪器，而是科学成像软件中的线段/箭头图形标注对象，用于在实验图像或数据视图上定义起点、终点、长度、角度和方向，并支持拖拽、微调与区域交互，常用于显微图像或其他科研数据的标记与测量辅助。",
  "description_en": "This is not a standalone physical instrument but a line/arrow graphic annotation object used in scientific imaging software. It defines a start point, end point, length, angle, and direction on experimental images or data views, and supports dragging, nudging, and interactive region editing for marking and measurement assistance in microscopy or other research datasets.",
  "actions": [
    {
      "action_name": "auto-vector",
      "description": "获取/设置线段向量。",
      "description_en": "Get/set the line vector."
    },
    {
      "action_name": "auto-start_arrow_enabled",
      "description": "获取/设置是否启用起点箭头。",
      "description_en": "Get/set whether the start arrow is enabled."
    },
    {
      "action_name": "auto-end_arrow_enabled",
      "description": "获取/设置是否启用终点箭头。",
      "description_en": "Get/set whether the end arrow is enabled."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "导出图形的 MIME 数据字典。",
      "description_en": "Export the graphic as a MIME data dictionary."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据读取图形内容。",
      "description_en": "Read the graphic from MIME data."
    },
    {
      "action_name": "auto-read_properties_from_dict",
      "description": "从字典读取图形属性。",
      "description_en": "Read graphic properties from a dictionary."
    },
    {
      "action_name": "auto-start",
      "description": "获取/设置线段起点。",
      "description_en": "Get/set the line start point."
    },
    {
      "action_name": "auto-end",
      "description": "获取/设置线段终点。",
      "description_en": "Get/set the line end point."
    },
    {
      "action_name": "auto-length",
      "description": "获取/设置线段长度。",
      "description_en": "Get/set the line length."
    },
    {
      "action_name": "auto-angle",
      "description": "获取/设置线段角度。",
      "description_en": "Get/set the line angle."
    },
    {
      "action_name": "auto-start_x",
      "description": "获取/设置起点 X 坐标。",
      "description_en": "Get/set the start-point X coordinate."
    },
    {
      "action_name": "auto-start_y",
      "description": "获取/设置起点 Y 坐标。",
      "description_en": "Get/set the start-point Y coordinate."
    },
    {
      "action_name": "auto-end_x",
      "description": "获取/设置终点 X 坐标。",
      "description_en": "Get/set the end-point X coordinate."
    },
    {
      "action_name": "auto-end_y",
      "description": "获取/设置终点 Y 坐标。",
      "description_en": "Get/set the end-point Y coordinate."
    },
    {
      "action_name": "auto-reset_position",
      "description": "重置线段位置。",
      "description_en": "Reset the line position."
    },
    {
      "action_name": "auto-test",
      "description": "测试命中或选中的线段部分。",
      "description_en": "Test which part of the line graphic is hit or selected."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始拖拽线段图形。",
      "description_en": "Begin dragging the line graphic."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束拖拽线段图形。",
      "description_en": "Finish dragging the line graphic."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "在交互过程中调整线段的选定部分。",
      "description_en": "Adjust a selected part of the line graphic during interaction."
    },
    {
      "action_name": "auto-nudge",
      "description": "对线段图形进行小幅移动。",
      "description_en": "Nudge the line graphic by a small offset."
    }
  ],
  "tag_hints": [
    "scientific image annotation",
    "line ROI",
    "interactive graphics",
    "distance marking",
    "arrow overlay",
    "microscopy image analysis"
  ]
}

